/* Matikan layer gambar lama agar path gambar yang gagal tidak mengganggu. */
#page-jadwal-togel .jadwal-card .jadwal-card-art{
  display:none!important;
}

/* Card menjadi kanvas artwork utama. */
#page-jadwal-togel .jadwal-card{
  position:relative!important;
  isolation:isolate!important;
  overflow:hidden!important;
  background-color:#001b15!important;
  background-repeat:no-repeat!important;
  background-size:cover!important;
}

/* Overlay kiri cukup gelap untuk teks, sisi kanan tetap menampilkan artwork. */
#page-jadwal-togel .jadwal-card .jadwal-card-shade{
  display:block!important;
  visibility:visible!important;
  position:absolute!important;
  z-index:2!important;
  inset:0!important;
  opacity:1!important;
  pointer-events:none!important;
  background:linear-gradient(90deg,
    rgba(0,27,21,.94) 0%,
    rgba(0,27,21,.85) 26%,
    rgba(0,25,19,.60) 43%,
    rgba(0,21,16,.25) 61%,
    rgba(0,14,11,.06) 82%,
    rgba(0,10,8,.02) 100%)!important;
}

#page-jadwal-togel .jadwal-card::before{
  z-index:3!important;
  background:linear-gradient(90deg,rgba(0,71,53,.46),rgba(0,52,41,.16) 58%,rgba(0,30,24,.01))!important;
}

#page-jadwal-togel .jadwal-card::after{
  z-index:4!important;
  opacity:.12!important;
}

#page-jadwal-togel .jadwal-card .jadwal-card-content{
  position:relative!important;
  z-index:7!important;
}
#page-jadwal-togel .jadwal-card .jadwal-card-title,
#page-jadwal-togel .jadwal-card .jadwal-card-slashes,
#page-jadwal-togel .jadwal-card .jadwal-card-edit{
  z-index:9!important;
}

